import { sql } from 'drizzle-orm'
import {
  check,
  index,
  pgTable,
  text,
  timestamp,
  uuid,
  uniqueIndex,
} from 'drizzle-orm/pg-core'
import { announcement } from '../announcements/announcement.schema'
import { complaint, complaintActivity } from '../complaints/complaint.schema'
import { createdAt, uuidv7PrimaryKey } from '../_shared/columns'
import { user } from '../auth/auth.schema'

/** Private inbox entries. Trusted business workflows create these for their recipients. */
export const notification = pgTable(
  'notification',
  {
    /** Time-ordered identity generated by PostgreSQL 18. */
    id: uuidv7PrimaryKey(),
    /** Account that alone may read or mark this entry as seen. */
    recipientId: text('recipient_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    /** Georgian summary authored by the originating workflow. */
    title: text('title').notNull(),
    /** Georgian message containing only information appropriate for the recipient. */
    body: text('body').notNull(),
    /** Optional company announcement destination; null for other notification workflows. */
    announcementId: uuid('announcement_id').references(() => announcement.id, {
      onDelete: 'restrict',
    }),
    /** Complaint destination with generic copy; opening independently rechecks current access. */
    complaintId: uuid('complaint_id').references(() => complaint.id, {
      onDelete: 'restrict',
    }),
    /** Durable change identity used to deduplicate per-recipient complaint alerts. */
    complaintActivityId: uuid('complaint_activity_id').references(
      () => complaintActivity.id,
      { onDelete: 'restrict' },
    ),
    /** Delivery instant, used with the identity for stable newest-first ordering. */
    createdAt: createdAt(),
    /** Explicit acknowledgement, cleared when the recipient marks the entry unseen again. */
    seenAt: timestamp('seen_at', { withTimezone: true }),
  },
  (table) => [
    uniqueIndex('notification_complaint_activity_recipient').on(
      table.complaintActivityId,
      table.recipientId,
    ),
    uniqueIndex('notification_announcement_recipient').on(
      table.announcementId,
      table.recipientId,
    ),
    index('notification_recipient_recent').on(
      table.recipientId,
      table.createdAt.desc(),
      table.id.desc(),
    ),
    index('notification_recipient_unseen')
      .on(table.recipientId)
      .where(sql`${table.seenAt} is null`),
    check(
      'notification_title_length',
      sql`length(trim(${table.title})) between 1 and 160`,
    ),
    check(
      'notification_body_length',
      sql`length(trim(${table.body})) between 1 and 2000`,
    ),
  ],
)
